const resolvers = {
  Query: { authors: () => db.all('SELECT * FROM authors') },
  Author: {
    posts: (author, _args, ctx) => ctx.loaders.postsByAuthor.load(author.id),
  },
};

function makeLoaders(db) {
  return {
    postsByAuthor: new DataLoader(async (ids) => {
      const rows = await db.all(`SELECT * FROM posts WHERE author_id IN (${ids.map(() => '?').join(',')})`, ids);
      return ids.map((id) => rows.filter((r) => r.author_id === id));
    }),
  };
}
